13	
14	\begin{lstlisting}[caption={update\_plan 的概念结构}]
15	{
16	  "explanation": "Why the plan is being updated",
17	  "plan": [
18	    {"step": "Inspect source files", "status": "in_progress"},
19	    {"step": "Patch implementation", "status": "pending"},
20	    {"step": "Run verification", "status": "pending"}
21	  ]
